<?php require_once __DIR__.'/../../helpers/bootstrap.php'; require_admin(); layout_start('Users'); $rows=db()->query('SELECT name,email,role,created_at FROM users ORDER BY id DESC')->fetchAll(); ?><h1>Users</h1><table><tr><th>Nama</th><th>Email</th><th>Role</th><th>Dibuat</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></table><?php layout_end();?>